let cocktails = msg.payload; // JSON-Array aus Excel
let zutatMap = {};

cocktails.forEach(cocktail => {
    // Array für alle Zutaten des aktuellen Cocktails
    let zutatenArray = [];

    // Alle Spalten, die Zutaten enthalten
    ["Spirituose", "Alkoholische Aromazutat", "Verlängerer", "Filler",
        "Frucht", "sonstige Zutaten", "Eis"].forEach(col => {
            if (cocktail[col]) {
                // Trennen bei Komma oder Semikolon
                let teile = cocktail[col].split(/[,;]+/).map(z => z.trim().toLowerCase());
                zutatenArray.push(...teile);
            }
        });

    // Map aufbauen: jede Zutat → Cocktails, inkl. kompletter Zutatenliste
    zutatenArray.forEach(zutat => {
        if (!zutatMap[zutat]) {
            zutatMap[zutat] = [];
        }
        zutatMap[zutat].push({
            name: cocktail.Cocktail,
            zutaten: zutatenArray // <-- hier speichern wir die **komplette Zutatenliste**
        });
    });
});

// Map global speichern
global.set("zutatMap", zutatMap);

return msg;
